/**
 * Build-time loader of the financial-model sub-pages of the memory topic (/memory/phison/, /memory/micron/).
 *
 * Reads src/data/memory/forecast/ — market-prices.yaml (shared price inputs), <company>-inputs.yaml (sourced
 * company inputs) and <company>-model.json (generated by scripts/models/<company>.ts) — and validates every file
 * with the zod schemas of src/schemas/forecast.ts. A missing file hides that company's page (and the links to it);
 * an invalid file fails the build with the schema issues (run npx tsx scripts/check-forecast.ts for details).
 *
 * Besides loading, this module owns the page conventions shared by the components in
 * src/components/memory/forecast/: period labels (calendar quarters for 群聯, Micron fiscal quarters), number
 * formatting (億元／億美元, %, EPS), the citation parsing of model text (raw source keys → [n] markers) and
 * pageSourceKeys(), the list of sources a page cites (registered before rendering so every [n] matches the list).
 */
import { existsSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { parse } from 'yaml';
import {
  companyInputs,
  marketPrices,
  modelOutput,
  type CompanyInputs,
  type MarketPrices,
  type ModelOutput,
} from '../schemas/forecast';
import type { SourceT } from '../schemas/common';
import { formatMoney, formatNumber, moneyUnitLabel, scaleMillions } from './format';
import { ROUTES, withBase } from './paths';

// ───────────── companies ─────────────

export type FcCompany = 'phison' | 'micron';
export const FC_COMPANIES: readonly FcCompany[] = ['phison', 'micron'];

