/** Site path of a model page: '/memory/phison/' (ROUTES.memoryPhison／memoryMicron in src/lib/paths.ts). */
export const forecastPath = (c: FcCompany): string => (c === 'phison' ? ROUTES.memoryPhison : ROUTES.memoryMicron);
export const forecastHref = (c: FcCompany): string => withBase(forecastPath(c));

// ───────────── loading ─────────────

export interface FcBundle {
  company: FcCompany;
  meta: FcMeta;
  inputs: CompanyInputs;
  model: ModelOutput;
  prices: MarketPrices;
  /** every source of the inputs and price files, keyed (key = the file's local key; keys are unique across files) */
  sourceByKey: Map<string, SourceT>;
}

const DIR = 'src/data/memory/forecast';
const fileOf = (f: string) => join(process.cwd(), DIR, f);
const filesFor = (c: FcCompany) => ['market-prices.yaml', `${c}-inputs.yaml`, `${c}-model.json`];

const cache = new Map<FcCompany, { stamp: string; data: FcBundle }>();

function stampOf(c: FcCompany): string {
  return filesFor(c)
    .map((f) => {
      try {
        return `${f}:${statSync(fileOf(f)).mtimeMs}`;
      } catch {
        return `${f}:-`;
      }
    })
    .join('|');
}

/** True when all three files of a company exist (the page and the links to it are built only then). */
export function hasForecast(c: FcCompany): boolean {
  return filesFor(c).every((f) => existsSync(fileOf(f)));
}

function load<T>(f: string, schema: { safeParse: (v: unknown) => { success: true; data: T } | { success: false; error: { issues: Array<{ path: PropertyKey[]; message: string }> } } }): T {
  const txt = readFileSync(fileOf(f), 'utf8');
  let raw: unknown;
  try {
    raw = f.endsWith('.json') ? JSON.parse(txt) : parse(txt);
  } catch (e) {
    throw new Error(`[forecast-data] ${DIR}/${f}: parse error: ${(e as Error).message}`);
  }
  const r = schema.safeParse(raw);
  if (!r.success) {
    const issues = r.error.issues.slice(0, 5).map((i) => `${i.path.map(String).join('.')}: ${i.message}`);
    throw new Error(`[forecast-data] ${DIR}/${f} does not match src/schemas/forecast.ts — ${issues.join('; ')} (run npx tsx scripts/check-forecast.ts)`);
  }
  return r.data;
}

export function getForecastData(c: FcCompany): FcBundle | undefined {
  if (!hasForecast(c)) {
    console.warn(`[forecast-data] ${c}: missing files in ${DIR}; the /memory/${c}/ page is skipped`);
    return undefined;
  }
  const stamp = stampOf(c);
  const hit = cache.get(c);
  if (hit && hit.stamp === stamp) return hit.data;
  const prices = load<MarketPrices>('market-prices.yaml', marketPrices);
  const inputs = load<CompanyInputs>(`${c}-inputs.yaml`, companyInputs);
  const model = load<ModelOutput>(`${c}-model.json`, modelOutput);
  if (inputs.company !== c || model.company !== c) throw new Error(`[forecast-data] ${c}: company mismatch in the inputs or model file`);
  const sourceByKey = new Map<string, SourceT>();
  for (const [k, s] of [...Object.entries(inputs.sources), ...Object.entries(prices.sources)]) {
    if (sourceByKey.has(k)) console.warn(`[forecast-data] ${c}: source key "${k}" is defined twice; the first one is used`);
    else sourceByKey.set(k, { ...s, key: k });
  }
  const data: FcBundle = { company: c, meta: FC_META[c], inputs, model, prices, sourceByKey };
  cache.set(c, { stamp, data });
  return data;
}

// ───────────── periods ─────────────

const RE_Q = /^(FY)?(\d{4})Q([1-4])$/;
const RE_Y = /^(FY)?(\d{4})$/;
const ZH_Q = ['', '一', '二', '三', '四'];

export const isQuarter = (p: string): boolean => RE_Q.test(p);
export const isYear = (p: string): boolean => RE_Y.test(p);

/** Sortable index of a quarter (FY and calendar quarters share the scale): 2026Q3 → 8106. */
export function qIndex(p: string): number {
  const m = RE_Q.exec(p);
  return m ? Number(m[2]) * 4 + Number(m[3]) - 1 : Number.NaN;
}

export function comparePeriods(a: string, b: string): number {
  const ka = isQuarter(a) ? qIndex(a) : Number(RE_Y.exec(a)?.[2] ?? 0) * 4 + 3.5;
  const kb = isQuarter(b) ? qIndex(b) : Number(RE_Y.exec(b)?.[2] ?? 0) * 4 + 3.5;
  return ka - kb;
}

/** Next quarter id in the same style: 2026Q4 → 2027Q1, FY2027Q4 → FY2028Q1. */
export function nextQuarter(p: string): string {
  const m = RE_Q.exec(p);
  if (!m) return p;
  const y = Number(m[2]);
  const q = Number(m[3]);
  return q === 4 ? `${m[1] ?? ''}${y + 1}Q1` : `${m[1] ?? ''}${y}Q${q + 1}`;
}

/**
 * Display labels. short: 「2026 Q3」「FY2027 Q1」「2027 年」「FY2027」; long: 「2026 年第三季」「FY2027 第一季」「2027 全年」「FY2027 全年」.
 */
export function periodLabel(p: string, style: 'short' | 'long' = 'short'): string {
  const q = RE_Q.exec(p);
  if (q) {
    const fy = !!q[1];
    if (style === 'long') return fy ? `FY${q[2]} 第${ZH_Q[Number(q[3])]}季` : `${q[2]} 年第${ZH_Q[Number(q[3])]}季`;
    return fy ? `FY${q[2]} Q${q[3]}` : `${q[2]} Q${q[3]}`;
  }
  const y = RE_Y.exec(p);
  if (y) return y[1] ? `FY${y[2]}${style === 'long' ? ' 全年' : ''}` : `${y[2]} ${style === 'long' ? '全年' : '年'}`;
  return p;
}

/**
 * Calendar months of a period: 2026Q3 → 「2026 年 7–9 月」; FY2027Q1 → 「約 2026 年 9–11 月」 (Micron's fiscal quarters
 * end on the Thursday closest to the end of Nov, Feb, May and Aug, so they can start or end a few days into the next
 * month: FY2027Q1 runs to early December 2026); FY2027 → 「約 2026 年 9 月至 2027 年 8 月」.
 */
export function calendarHint(p: string): string {
  const q = RE_Q.exec(p);
  if (q) {
    const y = Number(q[2]);
    const n = Number(q[3]);
    if (!q[1]) return `${y} 年 ${n * 3 - 2}–${n * 3} 月`;
    if (n === 1) return `約 ${y - 1} 年 9–11 月`;
    if (n === 2) return `約 ${y - 1} 年 12 月至 ${y} 年 2 月`;
    return n === 3 ? `約 ${y} 年 3–5 月` : `約 ${y} 年 6–8 月`;
  }
  const yr = RE_Y.exec(p);
  if (yr?.[1]) return `約 ${Number(yr[2]) - 1} 年 9 月至 ${yr[2]} 年 8 月`;
  return yr ? `${yr[2]} 年 1–12 月` : '';
}

/** Category key for MultiLine / bar charts: FY quarters become 「FY2026-Q4」 (grouped as FY26), others stay. */
export const chartKey = (p: string): string => p.replace(/^FY(\d{4})Q([1-4])$/, 'FY$1-Q$2');

/** Quarter ids from `from` to `to` inclusive. */
export function quarterRange(from: string, to: string): string[] {
  const out: string[] = [];
  let p = from;
  for (let i = 0; i < 200 && qIndex(p) <= qIndex(to); i++) {
    out.push(p);
    p = nextQuarter(p);
  }
  return out;
}

/** Calendar quarters overlapping a Micron fiscal quarter (FY2027Q1 → 2026Q3, 2026Q4). */
export function calendarQuartersOf(p: string): string[] {
  const q = RE_Q.exec(p);
  if (!q) return [];
  if (!q[1]) return [p];
  const y = Number(q[2]);
  const n = Number(q[3]);
  if (n === 1) return [`${y - 1}Q3`, `${y - 1}Q4`];
  if (n === 2) return [`${y - 1}Q4`, `${y}Q1`];
  if (n === 3) return [`${y}Q1`, `${y}Q2`];
  return [`${y}Q2`, `${y}Q3`];
}

// ───────────── numbers ─────────────

/** 「新台幣 861 億元」「603 億美元」 (amounts in millions; always in 億 so cards compare at a glance) */
export function fcMoney(millions: number | null | undefined, currency: string): string {
  if (millions == null || !Number.isFinite(millions)) return '—';
  return formatMoney(millions, currency, { unit: '億' });
}

/**
 * Number in 億 without the unit (tables with a unit header): 「861」「2,914」「6.1」. With explicit `digits` the
 * decimals are kept (「93.0」 next to 「98.5」), so a table column lines up.
 */
export function fcYi(millions: number | null | undefined, digits?: number): string {
  if (millions == null || !Number.isFinite(millions)) return '—';
  const v = scaleMillions(millions, '億');
  const d = digits ?? yiDigits(millions);
  return formatNumber(v, { digits: d, trim: digits == null });
}
/** Decimals fcYi uses for an amount in millions: 2 below 10 億, 1 below 100 億, else 0. */
export function yiDigits(millions: number): number {
  const v = Math.abs(scaleMillions(millions, '億'));
  return v < 10 ? 2 : v < 100 ? 1 : 0;
}

/** 「新台幣億元」「億美元」 */
export const fcYiUnit = (currency: string): string => moneyUnitLabel('億', currency);

/** 「65.1%」 (digits default 1) */
export function fcPct(v: number | null | undefined, digits = 1): string {
  if (v == null || !Number.isFinite(v)) return '—';
  return `${formatNumber(v, { digits })}%`;
}

/** Percent with the precision the source gives (guidance 86.25% stays 86.25%). */
export function fcPctExact(v: number | null | undefined): string {
  if (v == null || !Number.isFinite(v)) return '—';
  return `${formatNumber(v, { digits: 2, trim: true })}%`;
}

/** 「138.92 元」「37.30 美元」 */
export function fcEps(v: number | null | undefined, unit: string): string {
  if (v == null || !Number.isFinite(v)) return '—';
  return `${formatNumber(v, { digits: 2 })} ${unit}`;
}

/** Signed difference in percentage points: 「+2.5 個百分點」「−0.3 個百分點」 */
export function fcPp(v: number, digits = 1): string {
  return `${formatNumber(v, { digits, signed: true })} 個百分點`;
}

// ───────────── model helpers ─────────────

export type Candidate = ModelOutput['candidates'][number];
export type Scenario = ModelOutput['scenarios'][number];
export type ScenarioId = Scenario['id'];
export type Forecast = Scenario['forecasts'][number];
export type BacktestRow = ModelOutput['backtest'][number];
export type Quarter = CompanyInputs['quarters'][number];
export type Derived = ModelOutput['derived'][number];

export const SCENARIO_ORDER: readonly ScenarioId[] = ['bear', 'base', 'bull'];
/** Scenario colours, shared by the charts and the table headers (forecast.css uses the same tokens). */
export const SCENARIO_COLOR: Record<ScenarioId, string> = { bear: 'var(--chart-7)', base: 'var(--chart-2)', bull: 'var(--chart-3)' };

export const selectedCandidate = (m: ModelOutput): Candidate => m.candidates.find((c) => c.selected) ?? m.candidates[0]!;
export const scenarioOf = (m: ModelOutput, id: ScenarioId): Scenario | undefined => m.scenarios.find((s) => s.id === id);
export const forecastOf = (m: ModelOutput, id: ScenarioId, period: string): Forecast | undefined =>
  scenarioOf(m, id)?.forecasts.find((f) => f.period === period);
export const derivedOf = (m: ModelOutput, id: string): Derived | undefined => m.derived.find((d) => d.id === id);
export const paramOf = (m: ModelOutput, name: string) => m.parameters.find((p) => p.name === name);
export const paramStarting = (m: ModelOutput, prefix: string) => m.parameters.find((p) => p.name.startsWith(prefix));

/** Backtest rows of one candidate and metric, sorted by period. */
export function backtestOf(m: ModelOutput, candidate: string, metric: string): BacktestRow[] {
  return m.backtest.filter((b) => b.candidate === candidate && b.metric === metric).sort((a, b) => comparePeriods(a.period, b.period));
}

/** Forecast quarters (not years) of a scenario in order. */
export const forecastQuarters = (s: Scenario | undefined): Forecast[] => (s?.forecasts ?? []).filter((f) => isQuarter(f.period));

/** Quarter row of the inputs. */
export const quarterOf = (inp: CompanyInputs, p: string): Quarter | undefined => inp.quarters.find((q) => q.period === p);

/** The gross margin the model targets: 群聯 TIFRS gross profit ÷ revenue; 美光 non-GAAP gross margin. */
export function actualGrossMargin(c: FcCompany, q: Quarter): number | undefined {
  if (c === 'micron') return q.grossMarginNonGaap ?? (q.grossProfit != null ? (q.grossProfit / q.revenue) * 100 : undefined);
  return q.grossProfit != null ? (q.grossProfit / q.revenue) * 100 : undefined;
}
/** The EPS the model targets: 群聯 basic EPS; 美光 non-GAAP EPS. */
export const actualEps = (c: FcCompany, q: Quarter): number | undefined => (c === 'micron' ? (q.epsNonGaap ?? q.eps) : q.eps);

/** Quarters from `from` on (inclusive). */
export const quartersFrom = (inp: CompanyInputs, from: string): Quarter[] => inp.quarters.filter((q) => qIndex(q.period) >= qIndex(from));

/** Points of a market price series from a calendar quarter on. */
export function pricePoints(pr: MarketPrices, id: string, from?: string) {
  const s = pr.series.find((x) => x.id === id);
  if (!s) return { series: undefined, points: [] as MarketPrices['series'][number]['points'] };
  return { series: s, points: s.points.filter((p) => !from || !isQuarter(p.period) || qIndex(p.period) >= qIndex(from)) };
}

/** First calendar quarter of the price inputs plotted on a page (Micron: the one overlapping its first fiscal quarter). */
export function priceFrom(meta: FcMeta): string {
  return meta.id === 'micron' ? (calendarQuartersOf(meta.historyFrom)[0] ?? meta.historyFrom) : meta.historyFrom;
}

/** Micron's guidance for the first forecast quarter, read from the model parameters (undefined for 群聯). */
export interface NextGuidance {
  period: string;
  revenue: number;
  revenueLow?: number | undefined;
  revenueHigh?: number | undefined;
  grossMargin?: number | undefined;
  eps?: number | undefined;
  epsRange?: number | undefined;
  src?: string | undefined;
}
export function nextGuidance(b: FcBundle): NextGuidance | undefined {
  if (b.company !== 'micron') return undefined;
  const m = b.model;
  const period = forecastQuarters(scenarioOf(m, 'base'))[0]?.period;
  const rev = paramStarting(m, `${period} 財測：營收`);
  if (!period || !rev) return undefined;
  const gm = paramStarting(m, `${period} 財測：非 GAAP 毛利率`);
  const eps = paramStarting(m, `${period} 財測：非 GAAP EPS`);
  const pm = /±\s*([\d.]+)\s*億美元/.exec(rev.note ?? '');
  const em = /±\s*([\d.]+)\s*美元/.exec(eps?.note ?? '');
  const half = pm ? Number(pm[1]) * 100 : undefined;
  const src = /（([a-z0-9-]+)）/.exec(rev.note ?? '')?.[1];
  return {
    period,
    revenue: rev.value,
    revenueLow: half != null ? rev.value - half : undefined,
    revenueHigh: half != null ? rev.value + half : undefined,
    grossMargin: gm?.value,
    eps: eps?.value,
    epsRange: em ? Number(em[1]) : undefined,
    src: src && b.sourceByKey.has(src) ? src : undefined,
  };
}

// ───────────── citations in model text ─────────────

export type CitePart = string | { cite: string };

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\-]/g, '\\$&');
const reCache = new WeakMap<FcBundle, RegExp>();
function keyRe(b: FcBundle): RegExp {
  let re = reCache.get(b);
  if (!re) {
    const keys = [...b.sourceByKey.keys()].sort((x, y) => y.length - x.length).map(escapeRe);
    // not inside a marker that is already there (「⟦src:key⟧」 from a quarter range)
    re = new RegExp(`(?<![A-Za-z0-9:-])(${keys.join('|')})(?![A-Za-z0-9⟧-])`, 'g');
    reCache.set(b, re);
  }
  return re;
}

/**
 * Page conventions applied to the model's generated text (which keeps the raw units of the inputs): amounts in
 * 「百萬元」「百萬美元」 become 億 like the rest of the page (docs/STYLE-zh-TW.md: large numbers in 萬／億／兆), e.g.
 * 「86,076 百萬元」 → 「860.8 億元」; a hyphen-minus before a number becomes 「−」 (「誤差 -1.3%」 → 「誤差 −1.3%」).
 * Source keys (「tf-20260930-13258」) and dates are left alone: the minus rule needs a non-word character before it.
 */
export function fcPageText(text: string): string {
  return text
    .replace(/(\d[\d,]*(?:\.\d+)?)\s*百萬(美)?元/g, (_m, n: string, usd: string | undefined) => {
      const v = Number(n.replace(/,/g, '')) / 100;
      return `${formatNumber(v, { digits: v >= 1000 ? 0 : 1, trim: true })} 億${usd ? '美' : ''}元`;
    })
    .replace(/(^|[\s（(，、：；=＝])-(?=\d)/g, '$1−');
}

/**
 * Split model text into plain strings and citation markers: a raw source key such as 「（rm-fy2026q4）」 becomes [n];
 * a quarter range 「rm-fy2026q1–q4」 cites each quarter. Plain strings follow the page conventions (fcPageText).
 */
export function citeParts(b: FcBundle, text: string | null | undefined): CitePart[] {
  if (!text) return [];
  const has = (k: string) => b.sourceByKey.has(k);
  let t = text.replace(/\b((?:rm|pr|f|sec)-fy\d{4})q([1-4])–q([1-4])\b/g, (m, base: string, a: string, z: string) => {
    const ks: string[] = [];
    for (let i = Number(a); i <= Number(z); i++) if (has(`${base}q${i}`)) ks.push(`${base}q${i}`);
    return ks.length ? ks.map((k) => `⟦src:${k}⟧`).join('') : m;
  });
  t = t.replace(keyRe(b), (_m, k: string) => `⟦src:${k}⟧`);
  // 「（⟦a⟧、⟦b⟧）」 → markers only; 「…，⟦a⟧）」 → 「…⟦a⟧）」
  t = t.replace(/[（(]\s*((?:⟦src:[^⟧]+⟧[\s、，,]*)+)[）)]/g, (_m, inner: string) => inner.replace(/[\s、，,]+/g, ''));
  t = t.replace(/[，、]\s*((?:⟦src:[^⟧]+⟧)+)\s*(?=[）)])/g, '$1');
  const out: CitePart[] = [];
  let last = 0;
  for (const m of t.matchAll(/⟦src:([^⟧]+)⟧/g)) {
    if (m.index! > last) out.push(fcPageText(t.slice(last, m.index)));
    out.push({ cite: m[1]! });
    last = m.index! + m[0].length;
  }
  if (last < t.length) out.push(fcPageText(t.slice(last)));
  return out;
}

/** Keys cited inside a text (see citeParts). */
export const citesIn = (b: FcBundle, text: string | null | undefined): string[] =>
  citeParts(b, text).flatMap((p) => (typeof p === 'string' ? [] : [p.cite]));

/** Plain text with the citation markers removed (aria labels, chart notes). */
export const plainText = (b: FcBundle, text: string | null | undefined): string =>
  citeParts(b, text)
    .map((p) => (typeof p === 'string' ? p : ''))
    .join('')
    .replace(/（\s*）/g, '');

// ───────────── page sources ─────────────

/** Keys of the price-series points a page plots (its series, from priceFrom()). */
export function priceKeys(b: FcBundle): string[] {
  const from = priceFrom(b.meta);
  return b.meta.priceSeries.flatMap((id) => pricePoints(b.prices, id, from).points.map((p) => p.src));
}

/**
 * Every source a page cites, in list order (company sources first, then market prices). The components cite only
 * keys collected here: the model's sourceKeys and keys named in its text, scenario assumptions, events, annual
 * reports, monthly revenue, the quarters and guidance shown from meta.historyFrom on, and the plotted price points.
 */
export function pageSourceKeys(b: FcBundle): string[] {
  const { model: m, inputs } = b;
  const used = new Set<string>(m.sourceKeys);
  const addText = (s: string | undefined) => {
    for (const k of citesIn(b, s)) used.add(k);
  };
  addText(m.summary);
  for (const c of m.candidates) {
    addText(c.description);
    addText(c.note);
    c.equations.forEach(addText);
  }
  for (const p of m.parameters) addText(p.note);
  for (const d of m.derived) addText(d.note);
  for (const s of m.scenarios) {
    for (const a of s.assumptions) {
      if (a.src) used.add(a.src);
      addText(a.value);
    }
    for (const f of s.forecasts) addText(f.note);
  }
  for (const s of m.sensitivities) addText(s.effect);
  m.limitations.forEach(addText);
  for (const e of inputs.events) used.add(e.src);
  for (const a of inputs.annual) used.add(a.src);
  for (const mo of inputs.monthly) used.add(mo.src);
  for (const q of quartersFrom(inputs, b.meta.historyFrom)) {
    used.add(q.src);
    if (q.guidance) used.add(q.guidance.src);
  }
  for (const k of priceKeys(b)) used.add(k);
  const g = nextGuidance(b);
  if (g?.src) used.add(g.src);
  const order = [...Object.keys(inputs.sources), ...Object.keys(b.prices.sources)];
  for (const k of used) if (!b.sourceByKey.has(k)) console.warn(`[forecast-data] ${b.company}: cited key "${k}" has no source`);
  return order.filter((k) => used.has(k));
}

export function pageSources(b: FcBundle): SourceT[] {
  return pageSourceKeys(b).map((k) => b.sourceByKey.get(k)!);
}
